inline const FlowEdgeFact* flowEdgeFact(std::string_view className,
        u16 slot, u32 callVa) {
    for (const FlowEdgeFact& fact : kFlowEdgeFacts)
        if (fact.className == className && fact.vtableSlot == slot &&
            fact.callVa == callVa) return &fact;
    return nullptr;
}

